INSERT INTO `empleos` (`id`, `idempresa`, `titulo`, `descripcion`, `requisitos`, `beneficios`, `idexperiencia`, `vacantes`, `preciopromedio`, `fecha_publicacion`, `fecha_cierre`, `estado`, `userinsert`, `dateinsert`, `userupdate`, `dateupdate`) VALUES
(10, 1, 'Asistente de marketing - Lima', '<p>Descripción de la oferta laboral</p>', '<ul><li>Egresado de la carrea de marketing o  a fines.</li><li>Experiencia 1 año con las herramientas de Google</li></ul>', '<p>Planilla desde el primer día</p>', 3, '2', NULL, '2023-06-29 23:12:16', NULL, 'A', 'yfernandez@padin.com.pe', '2023-06-29 23:12:16', 'yfernandez@padin.com.pe', '2023-06-30 14:37:26'),
(11, 69, 'Analista de Marketing Digital', '<p><strong>Funciones:</strong></p><p>Desarrollar e implementar estrategias de marketing digital para aumentar la visibilidad y el reconocimiento de la marca en línea.</p><p>Crear y administrar campañas publicitarias en plataformas digitales.</p><p>Realizar análisis de mercado y seguimiento de la competencia para identificar oportunidades y tendencias en línea.</p><p>Optimizar el sitio web y otros canales digitales de la empresa para mejorar el posicionamiento en los motores de búsqueda.</p><p>Coordinar con la agencia de marketing y el área de diseño, para garantizar el cumplimiento del plan establecido.</p><p>Realizar análisis y seguimiento de métricas clave, como tráfico web, conversiones, ROI y KPIs de marketing digital.</p><p>Brindar soporte en tareas relacionadas a marketing tradicional.</p><p><br></p><p><br></p>', '<p>Estudios concluidos en Marketing, Administración o afines.</p><p>Minimo 1 año de experiencia en Marketing/Digital.</p><p>Conocimientos de E-Commerce, SEO y SEM.</p><p>Conocimientos de Marketing tradicional.</p><p>Conocimientos de Diseño básico</p><p>Disponibilidad para trabajar de lunes a viernes&nbsp;</p><p>Modalidad virtual</p>', NULL, 3, '2', NULL, '2023-06-30 01:32:46', NULL, 'A', 'mrodriguezp@padin.com.pe', '2023-06-30 01:32:46', NULL, NULL),
(12, 69, 'Diseñador Gráfico', '<ul><li>Desarrollar piezas gráficas de acuerdo con los requerimientos del área, velando por la calidad del material desarrollado.</li><li>Diseñar y adaptar piezas coherentes con la línea gráfica.</li><li>Realizar diseños para diarios, revistas y medios digitales.</li><li>Participar en el diseño y desarrollo de las campañas publicitarias, incluyendo el material publicitario.</li><li>Realizar el contenido para material multimedia.</li><li>Realizar otras funciones similares.</li></ul><p><br></p>', '<ul><li>Bachiller / Técnico en Diseño Gráfico o Publicidad.</li><li>Experiencia de 1 año en Marketing</li><li>Manejo de office nivel intermedio.</li><li>Conocimientos de Diseño editorial y web</li><li>Manejo y dominio de Creative Suite Adobe (Photoshop, Illustrator, In Design) a nivel intermedio.</li><li>Edición de video (Premier y after effects) a nivel intermedio.</li></ul><p><br></p>', NULL, 3, '2', NULL, '2023-06-30 01:37:08', NULL, 'A', 'mrodriguezp@padin.com.pe', '2023-06-30 01:37:08', NULL, NULL),
(13, 1, 'Asistente de MKT', '<p>...</p>', '<p>...</p>', '<p>...</p>', 2, '1', NULL, '2023-06-30 17:29:04', NULL, 'A', 'yfernandez@padin.com.pe', '2023-06-30 17:29:04', NULL, NULL),
(14, 1, 'Asistente de MKT', 'Lorem Ipsum is simply dummy text of the printing and typesetting industry.', 'Buscamos…', 'Lorem Ipsum is of the printing and typesetting industry.', NULL, '2', NULL, '2023-06-30 17:40:24', NULL, 'A', 'sistemas@padinsolutions.com', '2023-06-30 17:40:24', 'yfernandez@padin.com.pe', '2023-07-05 19:12:23'),
(15, 45, 'EJECUTIVO COMERCIAL', '<p>FUNCIONES</p><p>•	Prospección de nuevos clientes&nbsp;</p><p>•	Realizar estudios de mercado para identificar posibilidades de venta y evaluar las necesidades del cliente.</p><p>•	Buscar activamente nuevas oportunidades de venta</p><p>•	Fijar reuniones con posibles clientes y escuchar sus deseos y preocupaciones</p><p>•	Preparar y ofrecer presentaciones adecuadas sobre productos y servicios</p><p>HABILIDADES:</p><p>•	Buena comunicación</p><p>•	Orientación al cliente</p><p>•	Empatía y tolerancia</p><p>•	Organización y buen manejo del tiempo</p><p><br></p>', '<p>REQUISITOS</p><p>•	Estudiante a partir del 6to ciclo de la carrera de Dirección de Empresas, Negocios Internacionales y Marketing</p><p>•	Con o sin experiencia en el área comercial</p><p>•	Manejo en temas relacionados con atención al cliente</p><p>•	Manejo de herramientas informáticas a nivel usuario</p>', '<p>BENEFICIOS:</p><p>•	Pagos puntuales.</p><p>•	Bonos por cumplimiento de metas personales y de equipo.</p><p>•	Incentivos</p><p>•	Flexibilidad de horario</p><p>•	línea de carrera</p><p>•	Buen ambiente laboral</p><p><br></p>', 3, '2', 1025.00, '2023-06-30 21:25:02', NULL, 'A', 'RECURSOSHUMANOS@FIP413.COM', '2023-06-30 21:25:02', 'RECURSOSHUMANOS@FIP413.COM', '2023-06-30 21:36:50'),
(16, 9, 'Practicante Preprofeisonal - Auxiliar Comercial', '<p><span style=\"color: black;\">¿CUÁLES SERÁN TUS PRINCIPALES RESPONSABILIDADES?</span></p><p><span style=\"color: black;\">• Conectar a la empresa con posibles consumidores potenciales.</span></p><p><span style=\"color: black;\">• Generar y contactar a posibles clientes</span></p><p><span style=\"color: black;\">• Negociar acuerdos con los clientes.</span></p><p><span style=\"color: black;\">• Mantener la satisfacción del cliente.</span></p><p><span style=\"color: black;\">• Concretar ventas.</span></p>', '<p><span style=\"color: black;\">¿A QUIÉN BUSCAMOS?</span></p><p> <span style=\"color: black;\">• Estudiantes de la carrera de administración, gestión comercial, marketing o a fines.</span></p><p> <span style=\"color: black;\">• Persona activa y dinámica</span></p><p> <span style=\"color: black;\">• Dispuesto a trabajar en equipo</span></p><p> <span style=\"color: black;\">• Deseo de superación.</span></p><p> <span style=\"color: black;\">• Buena comunicación</span></p><p> <span style=\"color: black;\">• Orientación al cliente</span></p><p> <span style=\"color: black;\">• Empatía y tolerancia</span></p><p> <span style=\"color: black;\">• Organización y buen manejo del tiempo</span></p>', '<p><span style=\"color: black;\">¿QUÉ OFRECEMOS?</span></p><p> <span style=\"color: black;\">• Sueldo base según ley </span></p><p><span style=\"color: black;\"> • Comisiones</span></p><p> <span style=\"color: black;\">• Bonos, incentivos y reconocimientos</span></p><p> <span style=\"color: black;\">• Capacitación y entrenamiento constante</span></p><p> <span style=\"color: black;\">• Flexibilidad de horario</span></p><p> <span style=\"color: black;\">• Atractiva línea de carrera</span></p><p> <span style=\"color: black;\">• Buen ambiente laboral</span></p><p><span style=\"color: black;\"> • Convenio de prácticas pre profesionales</span></p>', 1, '5', 1025.00, '2023-06-30 21:39:55', NULL, 'A', 'aylluperusac@gmail.com', '2023-06-30 21:39:55', NULL, NULL),
(17, 9, 'Ejecutivo Comercial - Prácticas Profesionales', '<p><span style=\"color: black;\">¿A QUIÉN BUSCAMOS?</span></p><p> <span style=\"color: black;\">• Estudiantes de la carrera de administración, gestión comercial, marketing o a fines.</span></p><p> <span style=\"color: black;\">• Persona activa y dinámica</span></p><p> <span style=\"color: black;\">• Dispuesto a trabajar en equipo</span></p><p> <span style=\"color: black;\">• Deseo de superación.</span></p><p> <span style=\"color: black;\">• Buena comunicación</span></p><p> <span style=\"color: black;\">• Orientación al cliente</span></p><p> <span style=\"color: black;\">• Empatía y tolerancia</span></p><p> <span style=\"color: black;\">• Organización y buen manejo del tiempo</span></p>', '<p><span style=\"color: black;\">¿CUÁLES SERÁN TUS PRINCIPALES RESPONSABILIDADES?</span></p><p><span style=\"color: black;\">•Conectar a la empresa con posibles consumidores potenciales.</span></p><p> <span style=\"color: black;\">•Generar y contactar a posibles clientes</span></p><p> <span style=\"color: black;\">• Negociar acuerdos con los clientes.</span></p><p> <span style=\"color: black;\">• Mantener la satisfacción del cliente.</span></p><p> <span style=\"color: black;\">• Concretar ventas.</span></p>', '<p><span style=\"color: black;\">¿QUÉ OFRECEMOS?</span></p><p> <span style=\"color: black;\">• Sueldo base según ley </span></p><p><span style=\"color: black;\"> • Comisiones</span></p><p> <span style=\"color: black;\">• Bonos, incentivos y reconocimientos</span></p><p> <span style=\"color: black;\">• Capacitación y entrenamiento constante</span></p><p> <span style=\"color: black;\">• Flexibilidad de horario</span></p><p> <span style=\"color: black;\">• Atractiva línea de carrera</span></p><p> <span style=\"color: black;\">• Buen ambiente laboral</span></p><p><span style=\"color: black;\"> • Convenio de prácticas pre profesionales</span></p>', 1, '5', 1025.00, '2023-06-30 21:42:05', NULL, 'A', 'aylluperusac@gmail.com', '2023-06-30 21:42:05', NULL, NULL),
(18, 60, 'EJECUTIVO COMERCIAL', '<p>Empresa comercializadora industrial con presencia en 03 países y con un plan de crecimiento en la región LATAM busca Ejecutivo Técnico Comercial para incorporarse al staff comercial.</p>', '<p>- Generar y desarrollar cartera de clientes potenciales en la región LATAM.</p><p>- Gestionar y alcanzar metas de ventas mensuales con reportes semanales.</p><p>- Elaborar propuestas y presentaciones comerciales ( virtual / presencial ) para los clientes en la región LATAM.</p><p>- Elaborar reportes semanales y mensuales de las actividades realizadas. </p><p>- Mantener actualizado el sistema CRM con información sobre clientes y contactos. </p><p>- Incrementar la productividad de la cartera ejecutando las acciones para el logro de objetivos. Requisitos </p><p>- Estudios inconclusos o conclusos en Ingeniería Mecánica, Mecatrónica, Industrial a fines.</p><p>- Experiencia en ventas técnicas mínimo de tres (01) año.</p><p>- Disponibilidad para realizar viajes a provincia / internacionales LATAM. </p><p><br></p>', '<ul><li>Sueldo + Bonos por venta.</li><li>EPS.</li><li><br></li></ul>', 3, '1', 2000.00, '2023-06-30 22:00:46', NULL, 'A', 'HFIERRO@LUSANLATAM.COM', '2023-06-30 22:00:46', NULL, NULL),
(19, 77, 'ASESORES DE COBRANZAS ADMINISTRATIVAS - TRABAJA DE LUN A VIE - PLANILLA COMPLETA', '<p><br></p><p>&nbsp;</p>', '<p>¿Qué buscamos?</p><p>- Experiencia mínima de 6 meses en carteras administrativas o manejo de facturación, detracciones, guías de remisión, notas de crédito.</p><p>- Manejo de Excel nivel BASICO - INTERMEDIO, tablas dinámicas, fórmulas.</p><p>- Habilidades comunicativas y negociación.</p>', '<p>¿Qué ofrecemos?</p><p>&nbsp;</p><p>- Sueldo básico (1025) + comisiones.</p><p>- Bono de permanencia S/70</p><p>- Ingreso a planilla completa desde el primer día de gestión.</p><p>- Beneficios completos (Asignación Familiar, Seguro, CTS, gratificación y vacaciones).</p><p>- Capacitaciones cortas y pagadas.</p><p>- Pagos puntuales.</p><p>- Excelente clima laboral.</p><p>- Línea de carrera.</p><p>&nbsp;</p>', 2, '10', NULL, '2023-06-30 22:13:55', NULL, 'A', 'afranciat@hdec.com.pe', '2023-06-30 22:13:55', NULL, NULL),
(20, 50, 'Asesor Comercial', ' Ofrecer los productos de TELECOMUNICACIONES (telefonía móvil, internet dedicado, servicios de voz, renovaciones).', 'Estudios a nivel técnico o universitario truncos o en curso.Teleoperadores de Venta CON Experiencia mínima de 6 meses. Disponibilidad para laborar de manera PRESENCIAL Manejo de Microsoft office a nivel Usuario. en Surquillo ', 'Beneficios de Ley. Linea de Carrera. Exelente clima laboral', NULL, '10', NULL, '2023-06-30 22:23:25', NULL, 'A', 'sistemas@padinsolutions.com', '2023-06-30 22:23:25', NULL, NULL),
(21, 55, 'Ejecutivo Comercial de Tecnologías Microsoft', '<p><strong>Funciones:</strong></p><ul><li>Prospectar cartera asignada.</li><li>Calificar prospectos con búsquedas estandarizadas para ampliar cartera y ganar nuevos clientes.</li><li>Alcanzar y superar la cuota de ventas asignada.</li><li>Colaborar con los demás integrantes del equipo comercial, cuando sea requerido.</li><li>Elaborar propuestas y coordinar con el equipo de Preventa Técnica y Operaciones.</li><li>Dar seguimiento a propuestas y actualizar CRM.</li><li>Gestionar pipeline y forecast de ventas.</li><li>Presentar las credenciales de Kaits y “abrir” iniciativas.</li><li>Atender solicitudes inbound que lleguen al buzón info.</li><li>Supervisar la facturación de los servicios y licencias.</li><li>Participar en eventos generados por Marketing para relacionarse con los clientes.</li><li>Presentar informes de la gestión comercial de forma semanal y cuando sea requerido.</li><li>Capacitarse y certificarse en las tecnologías que le sean designadas.</li></ul><p><br></p>', '<ul><li>Egresados de las carreras de Administración, Negocios internacionales o similares.</li><li>Experiencia reciente de 2-5 años en venta de servicios de consultoría y desarrollo de software con tecnologías Microsoft: Microsoft BI &amp; Analytics, Power Platform, Aplicaciones .NET, IoT, IA, etc.</li><li>Evidenciar cartera de clientes propia.</li><li>Sólidas habilidades para prospectar y generar leads de forma semanal vía LinkedIn, WhatsApp, Mailing y Llamadas.</li><li>Conocimiento sólido del ciclo comercial y manejo de embudos, con fuertes destrezas en negociación y cierre.</li><li>Sólidas habilidades de presentación, comunicación asertiva y venta consultiva.</li><li>Conocimientos de Plataforma de Datos, Business Intelligence o Data Analytics.</li><li>Conocimiento de procesos de negocios: Ventas, Compras, Logística, Operaciones y/o Finanzas.</li><li>Inglés intermedio (fundamental para capacitarse con rapidez).</li><li>Capacidad de asimilar nuevo conocimiento con mucha rapidez.</li><li>Capacidad para organizarse y priorizar con rapidez.</li><li><span style=\"color: rgb(0, 0, 0);\">Contar con buena ortografía y redacción impecable</span></li></ul><p><br></p>', '<ul><li>Planilla desde el 1er día&nbsp;con todos los beneficios de ley.</li><li>Remuneración fija superior al mercado.</li><li>Seguro médico EPS&nbsp;para el titular, cubierto al 100% (Opcional para familiares directos).</li><li>Seguro Vida Ley.</li><li>Comisiones de ventas, adicionales a tu salario, por referir y participar en el proceso comercial, según la Política de Comisiones KAITS vigente.</li><li>Medio&nbsp;día libre por tu cumpleaños, además de cupones de tiempo libre.</li><li>Descuentos corporativos en restaurantes, cines y más.</li><li>Cubrimos la inversión de 02 exámenes de certificación Microsoft por año.</li><li>Oportunidad de crear relaciones valiosas con empresas de renombre y socios de clase mundial: Microsoft, Solver Inc y Nagnoi LLC.</li><li>Modalidad de Trabajo: Híbrido</li></ul>', 4, '2', 3500.00, '2023-06-30 23:19:03', NULL, 'A', 'cinthia.rojas@kaitsconsulting.com', '2023-06-30 23:19:03', 'cinthia.rojas@kaitsconsulting.com', '2023-06-30 23:20:44'),
(22, 17, 'Asesor / Asesora de Experiencias Part Time', '<p class=\"ql-align-center\"><br></p><p class=\"ql-align-justify\">¡Únete a nosotros! Cineplanet busca Asesoras y Asesores de Experiencia que, a través de su vocación de servicio, proactividad y buena actitud nos ayuden a cumplir nuestro propósito de “transformar un día común en historias extraordinarias”.</p><p>¡Prepárate para este reto!</p><p><br></p><p><strong>En tu día a día podrás:</strong></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ser anfitrión(a), recibiendo a los(as) clientes, guiándolos(as) a la ubicación de sus butacas y&nbsp;atendiéndolos(as) en el área de despacho de productos.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Realizar la producción del maíz y/u otros productos de la dulcería, apoyar a tus compañeros(as)&nbsp;en las diversas tareas del área.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Abastecer el almacén diario.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ser cajero(a), realizando la venta en el área de boletería.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Realizar la limpieza profunda de las salas, dulcería, boletería, baños y áreas comunes.</p><p><br></p><p><br></p><p class=\"ql-align-justify\">“Cineplanet es una empresa comprometida con la igualdad de oportunidades. Todas las personas que postulen serán consideradas sin importar su origen étnico, sexo, identidad sexual, expresión de genero , edad, estado civil, orientación sexual, religión, discapacidades, nacionalidad o condición económica”</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\"><br></p><p><br></p>', '<p>Acerca de ti:</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ser estudiante de una carrera técnica y/o universitaria.</p><p class=\"ql-align-justify\">-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Contar con disponibilidad de trabajar en horarios Part time</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tener toda la actitud y ganas de asumir retos en equipo.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Disponibilidad para laborar de manera inmediata.</p>', '<p><br></p><p>Tendrás grandes beneficios:</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Sueldo acorde al mercado con todos los beneficios de ley.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Un excelente clima laboral.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Trabajar cerca a tu domicilio.</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Descuentos Intercorp</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Capacitaciones constante</p>', 1, '20', 500.00, '2023-07-03 13:53:29', NULL, 'A', 'fminaya@cineplanet.com.pe', '2023-07-03 13:53:29', NULL, NULL),
(23, 59, 'DISEÑADOR GRAFICO', '<p>Importante empresa se encuentra en búsqueda de un Diseñador gráfico Part Time:&nbsp;</p><p><br></p><p>Funciones:</p><p>- Diseño de piezas gráficas</p><p>- Elaboración de propuesta y conceptos creativos (campañas y textos)</p><p>- Velar por el cumplimiento de la línea gráfica corporativa</p><p><br></p><p>Horario: 24 hrs semanales&nbsp;</p><p><br></p><p><br></p><p><br></p>', '<p>Requisitos:</p><p>- Carrera técnica: Diseño gráfico</p><p>- Manejo de Adobe suite (Ai, Lr, Ps)</p><p>- Conocimiento de formatos publicitarios (digitales e impresos)</p><p>- Correcta redacción&nbsp;</p><p>- Disponibilidad para laborar por 2 meses</p>', '<p>Beneficios:&nbsp;</p><p>Sueldo básico&nbsp;</p><p>Planilla desde el primer día de labores&nbsp;</p><p>Oportunidad de aprendizaje&nbsp;</p><p>Part Time</p><p>Trabajo Remoto</p>', 3, '1', 1025.00, '2023-07-03 14:27:15', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:27:15', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:29:37'),
(24, 59, 'Asistente Administrativo - Arequipa', '<p>Nuestro cliente, importante empresa localizada en el mercado de Cerro Colorado-Arequipa,</p><p>destacada en el rubro Metalmecánico, se encuentra en la búsqueda del/ los mejor(es) talento(s) para</p><p>ocupar el puesto de ASISTENTE ADMINISTRATIVO</p><p><br></p><p>HORARIO DE TRABAJO:</p><p>- Régimen Común trabajo 48 horas semanales de lunes a viernes y sábado medio día.</p><p><br></p><p>FUNCIONES:</p><p>- Encargado de las gestiones administrativas en obra, caja chica, selección de personal, revisión de</p><p>planillas, gestión proveedores, etc.</p><p><br></p><p><br></p><p>CANTIDAD DE VACANTES: 01</p>', '<p>REQUISITOS:&nbsp;</p><p>- Estudios mínimos: Universitarios (Contador, Administrador, Ing. Industrial)</p><p>- Experiencia mínima / Tiempo: 1 a 3 años de preferencia en puestos similares.</p><p>- Disponibilidad: Inmediato, lo antes posible.</p><p>- Disponibilidad de cambio de residencia o de viaje: No</p><p>- Manejo de sistemas informáticos: Office-básico.</p><p>- Dominio de idiomas: español.</p><p>- Licencia de Conducir: A1 no excluyente.</p><p>- Con Domicilio en Arequipa</p><p><br></p>', '<p>BENEFICIOS: (Indicar los solo beneficios brindados de acuerdo a la operación y al puesto)</p><p>- Agradable ambiente laboral.</p><p>- Ingreso directo a Planilla de Sucursales Establecidas en el Extranjero Cimolai SPA desde el primer día de labores con todos los Beneficios de Ley.</p><p>- Remuneración: Acorde al mercado</p><p>- Otros: Subvención alimentaria solo almuerzo (Lun a Vier), transporte a obra ida y vuelta por La Joya (Movilidad parte del puente Grau)</p><p>- Pertenecer a una empresa líder en el mercado</p>', 4, '1', NULL, '2023-07-03 14:34:02', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:34:02', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:42:37'),
(25, 59, 'Auxiliar Contable', '<p>Importante empresa se encuentra en búsqueda de un Auxiliar Contable Bilingüe que cumpla con el siguiente perfil:&nbsp;</p><p><br></p><p>Función principal: Registro de facturas</p><p><br></p><p>Horario de gestión: lunes a viernes, 8:00 am a 6:00 pm</p>', '<p>Requisitos:&nbsp;</p><p>Egresados y/o bachiller de la carrera profesional de&nbsp;Contabilidad.&nbsp;</p><p>Experiencia de 2 años en el cargo</p><p>Nociones de Contabilidad/Finanzas (indispensable)</p><p>De preferencia Experiencia SAP&nbsp;</p><p>Ingles hablado nivel avanzado.&nbsp;</p><p>Residir en Lima</p>', '<p>Beneficios:&nbsp;</p><p>Agradable clima laboral&nbsp;</p><p>Sueldo atractivo&nbsp;</p><p>Planilla con todos los beneficios desde el primer día de labores ( Regimen General).</p><p><br></p>', 4, '1', 3000.00, '2023-07-03 14:35:16', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:35:16', NULL, NULL),
(26, 59, 'Auxiliar de Infraestructira de TI', '<p><br></p><p>HORARIO DE TRABAJO:</p><p>De Lunes a Viernes de 08:30 a 18:30&nbsp;</p><p><br></p><p>FUNCIONES:</p><p>- Brindar soporte técnico a usuarios finales.</p><p>- Configurar aplicaciones de uso en la empresa.</p><p>- Brindar apoyo para coordinaciones con proveedores.</p><p>- Realizar las tareas asignadas por su superior inmediato, con apoyo y supervisión de su Jefe Tutor.</p><p>- Mantenimiento de equipos informáticos</p><p>- Revisar el inventario de TI</p><p>- Apoyar en las tareas de soporte, coordinaciones y demás encargadas por su Jefatura</p><p><br></p><p><br></p>', '<p>REQUISITOS&nbsp;</p><p>- Estudios mínimos: Título Técnico Superior, Estudios Universitarios Completos o Bachiller de Ingeniería de Sistemas o afines&nbsp;</p><p>- Experiencia mínima: 1 año de experiencia en funciones de Soporte Técnico</p><p>- Disponibilidad: Inmediata.</p><p>- Manejo de sistemas informáticos: Microsoft Office (Nivel Intermedio)</p><p>- Conocimiento en configuración e instalación de software y Hardware (deseable - 1 año de experiencia)</p><p>- Conocimiento en el uso de plataformas de Mesa de Ayuda (deseable - 1 año de experiencia)</p><p>- Conocimiento en programación (deseable - 1 año de experiencia)</p><p>- Con Domicilio en zonas cercanas a Miraflores.</p>', '<p>BENEFICIOS:&nbsp;</p><p>- Agradable ambiente laboral.</p><p>- Ingreso directo a Planilla de Obiettivo Lavoro desde el primer día de labores con todos los Beneficios de Ley.</p><p>- Remuneración: S/.1100.00</p><p>- Bono de S/.100.00&nbsp;</p><p>- Pertenecer a una empresa líder en el mercado</p>', 3, '1', 1200.00, '2023-07-03 14:37:33', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:37:33', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:42:19'),
(27, 59, 'Liquidador - Part Time', '<p>Por encargo de uno de nuestros clientes, una importante empresa embotelladora de consumo masivo, nos encontramos en la búsqueda de:&nbsp;</p><p><br></p><p>FUNCIONES:</p><p>- Recepción, revisión e ingreso de facturas, guías, boletas, notas de crédito.</p><p>- Generación de liquidaciones de cobranza.</p><p>- Atención a personal de almacén y choferes.</p><p>- Otras funciones inherentes al cargo.</p><p><br></p><p>LUGAR Y HORARIO DE TRABAJO:</p><p>- Lugar: Ate</p><p>- Horario de Lunes a sábado de 07:00 pm - 11:00 pm</p><p><br></p><p><br></p>', '<p>REQUISITOS:</p><p>- Estudios Técnicos concluidos en computación o afines.</p><p>- Manejo de Microsoft Office (Excel, Word, Power Point) Nivel Intermedio</p><p>- Conocimiento en SAP (Indispensable)</p><p>- Vivir cerca al distrito de Ate</p>', '<p>REMUNERACIÓN:</p><p>- Salario S/. 650 + S/ 100 bono por movilidad</p><p>- Ingreso a planilla con todos los beneficios de Ley.</p>', 2, '1', 750.00, '2023-07-03 14:39:22', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:39:22', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:42:01'),
(28, 59, 'DIGITADOR DE FACTURACION - SEDE ATE- TURNO NOCHE', '<p>Por encargo de uno de nuestros clientes, una importante empresa embotelladora de consumo masivo, nos encontramos en la búsqueda de:&nbsp;</p><p><br></p><p>FUNCIONES:</p><p>- Responsable de generación de pedidos Manuales.</p><p>- Contabilización de pedidos generados por la preventa del día.&nbsp;</p><p>- Generación de facturas, boletas, planillas de carga así como condiciones de pago y guías de remisión</p><p>- Remuneración de facturación.</p><p>- Generación de información referente al proceso. (Reporte de ventas, pedidos mal digitados, disponibilidad de stock, etc.)</p><p>- Llevar una gestión y control sobre las facturaciones que se den en cada centro.</p><p>- Otras funciones inherentes al cargo.</p><p><br></p><p>LUGAR Y HORARIO DE TRABAJO:</p><p>- Lugar: Ate</p><p>- Jornada Laboral: Lunes a Sábado</p><p>TURNOS : 6:30 pm a 3:30 am</p><p>Disposición de realizar Horas extras.</p><p><br></p><p><br></p><p><br></p>', '<p>REQUISITOS:</p><p>- Estudios técnicos concluidos o bachiller en administración, economía, contabilidad e ingeniería industrial</p><p>- Experiencia mínima de 1 año en puestos similares.</p><p>- Manejo de Excel a nivel intermedio</p><p>- Vivir cerca al distrito de Ate o zonas aledañas y tener disponibilidad para laborar en turno noche</p><p>- Debe contar con movilidad propia, ya que el turno de trabajo es de noche.</p>', '<p>REMUNERACIÓN:</p><p>- Salario: s/. 2,000 + S/.200.00 de movilidad</p><p>- Ingreso a planilla con todos los beneficios de ley</p>', 3, '1', 2200.00, '2023-07-03 14:41:41', NULL, 'A', 'luciacabrera@lavoroperu.pe', '2023-07-03 14:41:41', NULL, NULL),
(29, 21, 'Multifuncional', '<h3><strong>FUNCIONES: </strong></h3><ul><li>Atención al cliente. </li><li>Cobro de los productos en el área de caja. </li><li>Limpieza y orden de su área. </li><li>Realizar la recepción, almacenamiento y reposición de mercadería. </li><li>Cumplimiento de protocolos y procesos </li><li>Otras funciones afines que designe el jefe inmediato.</li></ul>', '<ul><li>Hombres o mujeres mayores de 18 años. </li><li>Con o Sin experiencia. </li><li>Disponibilidad para trabajar a Tiempo Completo de lunes a domingo con un día de descanso (Rotativo) o medio tiempo 4 días a la semana. </li><li>Disponibilidad para trabajar en CUALQUIER tienda de su distrito</li></ul>', '<ul><li>Planilla desde el primer día de labores. </li><li>Sueldo acorde el mercado. </li><li>Beneficios de acuerdo a ley correspondientes. </li><li>Beneficios y descuentos en el Grupo InterCorp. </li><li>Agradable clima laboral</li><li>Línea de carrera a corto plazo</li></ul>', 1, '20', 1025.00, '2023-07-03 14:56:33', NULL, 'A', 'lindsay.alpiste@spsa.pe', '2023-07-03 14:56:33', NULL, NULL),
(30, 21, 'Supervisor/a de Tienda', '<h3><strong>Funciones</strong>:</h3><p><br></p><ul><li>Atención al cliente. </li><li>Realizar cuadre de caja, inventarios y velar por el mantenimiento de tienda. </li><li>Apoyar al Administrador de Tienda. </li><li>Verificar y colaborar en la limpieza de las áreas productos y equipos de la tienda. </li><li>Supervisar las labores del personal en los diferentes turnos.</li></ul>', '<ul><li>Técnico culminado o inconcluso. </li><li>Disponibilidad para trabajar en Horarios Rotativos (INDISPENSABLE) </li><li>Disponibilidad para trabajar en CUALQUIER tienda de su distrito</li><li>Contar con experiencia mínima de 1 año como Reponedor, Almacenero o Cajero en empresas del rubro retail / fastfood / grifos / etc. (INDISPENSABLE) </li><li>Contar con experiencia mínima de 6 meses teniendo personal a cargo (INDISPENSABLE).</li></ul>', '<ul><li>Salario acorde al mercado + Bono de Pasajes + Bono de Alimentación + Bono por Objetivos </li><li>Planilla, con todos los beneficios de ley correspondientes. </li><li>Incorporarse al segundo empleador más grande del país, con estabilidad laboral. </li><li>Capacitaciones constantes.</li><li>Beneficios y descuentos en el Grupo InterCorp</li></ul>', 2, '20', 1200.00, '2023-07-03 14:59:29', NULL, 'A', 'lindsay.alpiste@spsa.pe', '2023-07-03 14:59:29', NULL, NULL),
(31, 21, 'Administrador@s de Tienda', '<h4><strong>FUNCIONES</strong>: </h4><p><br></p><ul><li>Verificar el cumplimiento total del layout de la tienda, realización de inventarios. </li><li>Representante de la empresa ante inspecciones y/o fiscalizaciones por parte de entidades gubernamentales. </li><li>Solucionar problemas presentados tanto con clientes y proveedores y/o cualquier persona que ingrese a la tienda. </li><li>Responsable de la gestión de tienda y KPI e inventarios. </li><li>Verificar y colaborar en la limpieza de las áreas, productos y equipos de la tienda. </li><li>Supervisar las labores del personal en los diferentes turnos.</li></ul>', '<ul><li>Experiencia liderando unidades de negocio (Fast food, restaurantes, tiendas) </li><li>Estudios Culminados en Administración de Empresas o carreras afines. </li><li>Conocimiento de Indicadores de gestión. </li><li>Disponibilidad para trabajar en horarios rotativos. </li><li>Disponibilidad para trabajar en CUALQUIER tienda de su distrito</li></ul>', '<ul><li>Salario acorde al mercado + Bono de Pasajes + Bono de Alimentación + Bono por Objetivos </li><li>Planilla, con todos los beneficios de ley correspondientes. </li><li>Incorporarse al segundo empleador más grande del país, con estabilidad laboral. </li><li>Capacitaciones constantes. </li><li>Beneficios y descuentos en el Grupo InterCorp</li></ul>', 3, '20', 1800.00, '2023-07-03 15:02:33', NULL, 'A', 'lindsay.alpiste@spsa.pe', '2023-07-03 15:02:33', NULL, NULL),
(32, 46, 'Asesor de ventas - Movistar Empresa', '<p class=\"ql-align-justify\">¡EN FOXTEL BUSCAMOS TALENTOS COMO TÚ!</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Se parte de FOXTEL, grupo empresarial con más de 14 años de experiencia en el rubro de telecomunicaciones y actualmente socio estratégico de MOVISTAR.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Nos encontramos en la búsqueda de nuevos talentos que ocupen el puesto de <strong>ASESOR DE VENTAS</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Requisitos:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Habilidades comunicativas.</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Gestión comercial </p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Trabajo Presencial.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Funciones:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Prospección vía telefónica y seguimiento a clientes (Se brindará base de datos).</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Venta de servicios (movil y fija) de manera telefónica. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Remuneración Básica: desde S/1025 hasta S/2,000 (según experiencia laboral comprobada)</p><p class=\"ql-align-justify\">Comisiones: al 100 % sin tope de cargo fijo vendido.</p><p class=\"ql-align-justify\">Horario: lunes a viernes de 9 a.m. a 6 p.m. </p><p class=\"ql-align-justify\">Lugar de Labores: Av. José Gálvez Barrenechea 190 – La Victoria, Lima.</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p class=\"ql-align-justify\">¡TE INVITAMOS A PERTENECER A UN GRAN EQUIPO!</p><p><br></p>', '<p>Desde 6 meses como mínimo de experiencia como asesor, promotoría y/o atención al cliente. </p>', '<p>Beneficios de Ley. </p>', 2, '10', NULL, '2023-07-03 15:30:47', NULL, 'A', 'ssoria@telefonianegocios.pe', '2023-07-03 15:30:47', NULL, NULL),
(33, 52, 'PRACTICANTE DISEÑADOR  GRAFICO', '<p class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(32, 33, 36);\">Somos ISM Ingeniería &amp; Consultoría</strong><span style=\"background-color: transparent; color: rgb(32, 33, 36);\">, empresa dedicada a brindar soluciones de ingeniería relacionadas a la construcción de obras en general, servicios electromecánicos y elaboración de proyectos de ingeniería bajo rigurosos estándares de calidad y seguridad. Actualmente, nos encontramos en</span><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"> la búsqueda de un PRACTICANTE DE DISEÑO GRÁFICO. Buen ambiente laboral.</span></p><p class=\"ql-align-justify\"><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Envía tu portafolio + cv a: </span><a href=\"mailto:ism.ictalentohumano@gmail.com\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"background-color: transparent; color: rgb(17, 85, 204);\">ism.ictalentohumano@gmail.com</a><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"> con el asunto “PDG-01” o contáctanos al: 993012457</span></p>', '<p class=\"ql-align-justify\"><br></p><ul><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Estudiantes de los últimos ciclos de Diseño Gráfico, Comunicaciones o afines.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Manejo de Adobe Photoshop, Illustrator, Premiere y After Effects.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Oportunidad de desarrollo y línea de carrera.</span></li></ul><p><br></p>', NULL, 2, '2', 180.00, '2023-07-03 15:49:40', NULL, 'A', 'ism.ictalentohumano@gmail.com', '2023-07-03 15:49:40', 'ism.ictalentohumano@gmail.com', '2023-07-03 21:50:17'),
(34, 89, 'Team Leader', '<p>Somos Verisure Perú, compañía especializada en sistemas de seguridad electrónica de alta tecnología y líder en el mercado europeo. Con 30 años de presencia en Europa y Latinoamérica, Verisure se encuentra en total desarrollo y transformación tecnológica, ofreciendo a nuestros clientes la confianza y seguridad necesaria para proteger lo que más les importa. Además, se encuentra&nbsp;certificada como una de las mejores empresas para trabajar, por Great Place to Work.&nbsp;Es por ello que actualmente nos encontramos en la búsqueda del mejor talento para cubrir la posición de un(a)&nbsp;Team Líder - Televentas</p><p><br></p><p><br></p><p>FUNCIONES:</p><p><br></p><ul><li>Monitorear la campaña de ventas y el equipo de trabajo a su cargo.</li><li>Realizar reportes de indicadores de gestión de la campaña, determinar planes y acciones de mejora.</li><li>Participar de la selección y captación de nuevos operadores.</li><li>Realizar auditorías a las llamadas del equipo de ventas, en base a objetivos estableciendo planes de mejora.</li><li>Asegurar el cumplimiento de los procesos de documentación y realizar las coordinaciones con el área de facturación asegurando el 100% de las ventas facturadas.</li><li>Verificar la conformidad del servicio con los clientes.</li><li>Gestionar un equipo entre 10 a 14 personas.</li><li>Validar los datos de los clientes a través del Verismart</li><li>Verificar el historial crediticio de los clientes a través de Sentinel y/o Equifax</li><li>Utilizar las plataformas de Genesys y Work Space.</li><li>Validar y evitar cruces de ventas a través de Infopoint.</li></ul><p><br></p><p><br></p><p><br></p><p><br></p>', '<p>REQUSITOS:</p><p><br></p><p><br></p><ul><li>Bachiller en la carrera de Administración de Empresas, Economía, Ingeniería Industrial o afines.</li><li>Mínimo 2 años de experiencia realizando funciones similares.</li><li>Office a nivel intermedio.</li><li>Experiencia liderando equipos de televentas y/o telemarketing.</li></ul><p><br></p>', '<p>BENEFICIOS:</p><p><br></p><ul><li>Todos los beneficios de ley.</li><li>EPS cubierta al 8 0% a partir del 3er mes.</li><li>Agradable clima laboral.</li><li>Bono de Alimentación.</li><li>Línea de carrera.</li><li>Capacitaciones a través de Workday Learning.</li></ul><p><br></p><p>Verisure Perú es una empresa que promueve y garantiza el desarrollo profesional de sus colaboradores en un ambiente de igualdad y respeto, fomentando además que todos tengan las mismas oportunidades de crecimiento y mejora. Además, desde la postulación orientamos a las personas con discapacidad e inclusión laboral en nuestros diferentes procesos de reclutamiento, según la LEY N° 29973, en pro de la protección y promoción en condiciones de igualdad.</p><p><br></p><p><br></p><p>\"Vamos, qué esperas para ser parte del equipo de trabajo de Verisure”</p>', 4, '1', NULL, '2023-07-03 16:38:21', NULL, 'A', 'celina.morales@verisure.pe', '2023-07-03 16:38:21', NULL, NULL),
(35, 89, 'Supervisor de Contact Center', '<p>Somos Verisure Perú, compañía especializada en sistemas de seguridad electrónica de alta tecnología y líder en el mercado europeo. Con 30 años de presencia en Europa y Latinoamérica, Verisure se encuentra en total desarrollo y transformación tecnológica, ofreciendo a nuestros clientes la confianza y seguridad necesaria para proteger lo que más les importa. Además, se encuentra certificada como una de las mejores empresas para trabajar, por Great Place to Work. Es por ello que actualmente nos encontramos en la búsqueda del mejor talento para cubrir la posición de un(a) Supervisor de Contact Center</p><p><br></p><p>Funciones:</p><p><br></p><ul><li>Supervisar la campaña de ventas y el equipo de trabajo a su cargo.</li><li>Analizar reportes de indicadores de gestión de la campaña, determinar planes y acciones de mejora.</li><li>Dar seguimiento, distribución y mejoras de la base de datos asignada.</li><li>Ser el responsable de la selección y captación de nuevos operadores.</li><li>Gestionar y auditar las llamadas del equipo de ventas, en base a objetivos estableciendo planes de mejora.</li><li>Realizar el seguimiento de los Indicadores de Gestión.</li><li>Asegurar el cumplimiento de los objetivos.</li><li>Gestionar un equipo entre 1 0 a 1 4 personas.</li><li>Mantener una actitud motivadora en todo momento, ser entusiasta, positivo, comunicativo y orientado hacia el trabajo en equipo.</li><li>Validar y evitar cruces de ventas a través de Infopoint.</li><li>Utilizar la plataforma de Workspace</li><li>Utilizar las herramientas Equifax, Genesys.</li></ul><p><br></p><p>Verisure Perú es una empresa que promueve y garantiza el desarrollo profesional de sus colaboradores en un ambiente de igualdad y respeto, fomentando además que todos tengan las mismas oportunidades de crecimiento y mejora. Además, desde la postulación orientamos a las personas con discapacidad e inclusión laboral en nuestros diferentes procesos de reclutamiento, según la LEY N° 2 9 9 7 3, en pro de la protección y promoción en condiciones de igualdad.</p><p><br></p><p>\"Vamos, qué esperas para ser parte del equipo de trabajo de Verisure”</p>', '<ul><li>Egresado universitario y/o técnico en Administración, Contabilidad y/o carreras afines.</li><li>Experiencia mínima de 3 años como Supervisor de televentas de preferencia en el sector bancario, call center.</li><li>Experiencia liderando equipos de 1 0 a 1 5 ejecutivos como mínimo.</li><li>Excel a nivel avanzado.</li><li>Manejo de KPI´S.</li></ul><p><br></p>', '<ul><li>Ingreso a planilla con todos los beneficios de ley.</li><li>Contrato a plazo indeterminado.</li><li>Bono de alimentación.</li><li>Cobertura de EPS y Seguro oncológico.</li><li>Agradable clima laboral.</li><li>Oportunidad de crecimiento.</li></ul><p><br></p>', 5, '1', NULL, '2023-07-03 16:40:18', NULL, 'A', 'celina.morales@verisure.pe', '2023-07-03 16:40:18', NULL, NULL),
(36, 36, 'Ingeniero de datos AWS', '<p>• Universitario titulado en la carrera de Ingeniería de Sistemas de Información, Ingeniería de Sistemas, Software, Ciencia de la Computación o afines.</p><p>• Experiencia mínimo 6 años en proyectos de banca, telecomunicación, retail o seguro</p>', '<p>Conocimientos:</p><p>• Base de datos PLQ/ SQL, Oracle (avanzado)</p><p>• Python (minimo 4 años)</p><p>• ETLs</p><p>• Big data</p><p>• AWS (minimo 1 año de experiencia laboral)</p><p>• Teradata (deseable)</p><p>• Marcos de metodología</p><p><br></p>', '<p>• Planilla completa desde el primer dia</p><p>• Capacitaciones</p><p>• Linea de carrera</p><p>• EPS cubierto al 30%</p><p>• Buen clima laboral</p>', 5, '3', 8000.00, '2023-07-03 17:06:03', NULL, 'A', 'patricia.campos@dwconsulware.com', '2023-07-03 17:06:03', NULL, NULL),
(37, 15, 'ASESOR DE NEGOCIOS CON/SIN EXPERIENCIA - AGENCIA PRO LOS OLIVOS', '<p><strong>Somos Great Place to Work-Certificada ™</strong></p><p>Caja Huancayo es una empresa líder del sector microfinanciero que ofrece una experiencia de trabajo de estándares mundiales a sus colaboradores, organización que está comprometida con construir y mantener una cultura empresarial de alta confianza.</p><p>Únete a este gran equipo como: <strong>ASESOR DE NEGOCIOS CON/SIN EXPERIENCIA - AGENCIA PRO LOS OLIVOS</strong></p><p><br></p><p><span class=\"ql-cursor\">﻿﻿</span>¿Cómo postular a Caja Huancayo?</p><ol><li>Para participar de nuestra convocatoria, te invitamos a&nbsp;registrar tus datos en nuestro portal web www.trabajaencajahuancayo.com.pe Sección REGÍSTRATE; una vez que ingreses tu información, podrás INICIAR SESIÓN y POSTULAR a la presente convocatoria.</li><li>Fecha límite de postulación:&nbsp;0 5. 0 7. 2 0 2 3</li><li>Se solicita estar pendientes de nuestras comunicaciones y resultados a través de nuestra página web https://www.trabajaencajahuancayo.com.pe/</li></ol><p><br></p><p><strong>¿Qué retos alcanzarás?</strong></p><p>Ejecutar el proceso de promoción, otorgamiento, seguimiento y recuperación de créditos, cumpliendo con las normas internas y externas establecidas, para alcanzar las metas propuestas y un crecimiento sostenible de su cartera.</p>', '<ul><li>Egresado técnico de carreras de Ciencias Administrativas, Ciencias Contables, Computación e Informática o equivalentes, y otros (agronomía, agropecuaria), o;</li><li>Estudiante universitario del séptimo semestre de las carreras de Ciencias Administrativas; Ciencias Económicas, Ciencias Contables, Ingenierías o equivalentes, o;</li><li>Egresado universitario o egresado técnico de cualquier carrera, siempre y cuando tenga por lo menos 06 meses de experiencia demostrada en el otorgamiento de créditos y cuente con una especialización en finanzas o afines.</li></ul><p>Otros:</p><ul><li>Comprobada solvencia moral (clasificación crediticia del deudor 1 0 0% normal en el sistema financiero correspondiente al último RCC vigente).</li><li>No contar con antecedentes penales, judiciales y policiales.</li></ul><p>¿Qué experiencia buscamos?</p><p>Para asesores de negocios con experiencia: Seis (06) meses de experiencia demostrada en evaluación, otorgamiento y recuperación de créditos. Para asesores de negocios sin experiencia: No requiere.</p>', '<ul><li>Formarás parte de la institución líder en el sector microfinanciero, con sólida presencia a nivel nacional.</li><li>Ingresarás a planilla con todos los beneficios de Ley.</li><li>Creceremos juntos y tendrás la posibilidad de desarrollar línea de carrera dentro de nuestra Organización.</li><li>Te proporcionamos bonos por productividad.</li><li>Serás parte de un gran equipo que cuenta con un grato ambiente de trabajo.</li><li>Convenios educativos.</li><li>Tendrás acceso a un programa de beneficios creado exclusivamente para nuestros colaboradores.</li></ul>', 2, '2', 1452.00, '2023-07-03 17:08:28', NULL, 'A', 'lperez@cajahuancayo.com.pe', '2023-07-03 17:08:28', 'lperez@cajahuancayo.com.pe', '2023-07-03 17:10:23'),
(38, 30, 'ASESOR MULTISKILL', '<p>Corporación SIC, empresa con más de 25 años de trayectoria como franquicia de MOVISTAR, se encuentra en la búsqueda de personas con entusiasmo y buena actitud orientados a la atención de nuestros clientes para ocupar el puesto de:</p><p><br></p><p>Asesor de Atención al cliente y Ventas/ Tiendas Movistar Miraflores (Av. Benavides 671)</p><p><br></p><p>¿Qué buscamos?</p><p>- Personal con 6 meses de experiencia en atención al cliente, ventas o afines.&nbsp;</p><p>- Educación Secundaria completa.&nbsp;</p><p>- Conocimiento y manejo de office a nivel usuario.</p><p>- Disponibilidad para laborar tiempo completo</p><p><br></p><p>FUNCIONES</p><p>-Brindar una atención de calidad cumpliendo los estándares de atención establecidos por Movistar para ventas, atenciones consultas y reclamos que garanticen la Satisfacción del cliente.</p><p>-Realizar labor de abordaje al mayor porcentaje de clientes.</p><p>-Cumplir con los procedimientos y normativas de atención.</p><p>-Generar oportunidad de venta de nuestros productos a los clientes que sean atendidos.&nbsp;</p><p>-Llevar orden y control de documentos que sustenten las operaciones realizadas.</p><p><br></p><p>¿ Que te otorgamos ?&nbsp;</p><p>- Sueldo básico + asignación familiar + Comisiones ilimitadas</p><p>- Todos los beneficios de Ley&nbsp;</p><p>- Ingreso directo a planilla completa</p><p>- Capacitaciones constantes</p><p>- Crecimiento constante y línea de carrera a partir del 3er mes.</p><p>- Convenios con universidades e institutos.</p><p>- Excelente clima laboral.</p><p><br></p><p>Anímate y se parte de nuestra familia SIC</p>', '<p>FUNCIONES</p><p>-Brindar una atención de calidad cumpliendo los estándares de atención establecidos por Movistar para ventas, atenciones consultas y reclamos que garanticen la Satisfacción del cliente.</p><p>-Realizar labor de abordaje al mayor porcentaje de clientes.</p><p>-Cumplir con los procedimientos y normativas de atención.</p><p>-Generar oportunidad de venta de nuestros productos a los clientes que sean atendidos.&nbsp;</p><p>-Llevar orden y control de documentos que sustenten las operaciones realizadas.</p><p><br></p>', '<p>¿ Que te otorgamos ?&nbsp;</p><p>- Sueldo básico + asignación familiar + Comisiones ilimitadas</p><p>- Todos los beneficios de Ley&nbsp;</p><p>- Ingreso directo a planilla completa</p><p>- Capacitaciones constantes</p><p>- Crecimiento constante y línea de carrera a partir del 3er mes.</p><p>- Convenios con universidades e institutos.</p><p>- Excelente clima laboral.</p><p><br></p>', 2, '10', 1025.00, '2023-07-03 18:09:34', NULL, 'A', 'waznaran@sic.com.pe', '2023-07-03 18:09:34', NULL, NULL),
(39, 30, 'ANFITRIONES', '<p>Empresa Corporación SIC, franquicia N 01 de MOVISTAR, administrando oficinas a nivel Nacional para la atención de sus clientes y comercialización de productos/servicios; requiere personal con actitud, calidad de atención y vocación de servicio para el puesto de Anfitrión..</p><p><br></p><p>Requisitos:</p><p>-Experiencia Laboral: Experiencia laboral en atención al cliente mínima de 06 meses</p><p>-Disponibilidad para trabajar en horarios Full-time / Lunes a domingo (1 día de descanso a la semana).</p><p><br></p><p><br></p><p>Funciones:&nbsp;</p><p>-Brindar una atención de calidad cumpliendo los estándares de atención establecidos por Movistar para ventas, atenciones consultas y reclamos que garanticen la Satisfacción del cliente.&nbsp;</p><p>-Realizar labor de abordaje al mayor porcentaje de clientes.</p><p>-Cumplir con los procedimientos y normativas de atención&nbsp;</p><p>-Generar oportunidad de venta de nuestros productos a los clientes que sean atendidos.&nbsp;&nbsp;</p><p>-Llevar orden y control de documentos que sustenten las operaciones realizadas.&nbsp;</p><p><br></p><p>Beneficios:&nbsp;</p><p>- Sueldo S/.1025</p><p>- Capacitaciones&nbsp;&nbsp;</p><p>- Ingreso a Planilla desde el primer día.</p><p>- Todos los beneficios de ley al 100%</p><p>- Oportunidad de línea de carrera a partir de 3er mes</p>', '<p>Funciones:&nbsp;</p><p>-Brindar una atención de calidad cumpliendo los estándares de atención establecidos por Movistar para ventas, atenciones consultas y reclamos que garanticen la Satisfacción del cliente.&nbsp;</p><p>-Realizar labor de abordaje al mayor porcentaje de clientes.</p><p>-Cumplir con los procedimientos y normativas de atención&nbsp;</p><p>-Generar oportunidad de venta de nuestros productos a los clientes que sean atendidos.&nbsp;&nbsp;</p><p>-Llevar orden y control de documentos que sustenten las operaciones realizadas.&nbsp;</p>', '<p>Beneficios:&nbsp;</p><p>- Sueldo S/.1025</p><p>- Capacitaciones&nbsp;&nbsp;</p><p>- Ingreso a Planilla desde el primer día.</p><p>- Todos los beneficios de ley al 100%</p><p>- Oportunidad de línea de carrera a partir de 3er mes</p>', 2, '5', 1025.00, '2023-07-03 18:11:24', NULL, 'A', 'waznaran@sic.com.pe', '2023-07-03 18:11:24', NULL, NULL);
INSERT INTO `empleos` (`id`, `idempresa`, `titulo`, `descripcion`, `requisitos`, `beneficios`, `idexperiencia`, `vacantes`, `preciopromedio`, `fecha_publicacion`, `fecha_cierre`, `estado`, `userinsert`, `dateinsert`, `userupdate`, `dateupdate`) VALUES
(40, 39, 'Ejecutivo de Trade Marketing - Callao', '<ul><li><span style=\"color: rgb(81, 74, 72);\">Zona asignada LIMA NORTE - Trabajo de campo por lo menos 3 veces a la semana.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Velar por el desarrollo de la marca en todos los canales y puntos de ventas (más de 200 a nivel nacional) – 24 tiendas propias.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Visitar tiendas y revisar las exhibiciones. Realizar la ruta de visita de acuerdo a la necesidades de cada punto de venta y prioridades.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Investigar el mercado, competencia y estar alerta a las necesidades de los puntos de ventas y tiendas.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Supervisar las exhibiciones de tiendas – Tener constante comunicación con tiendas, KAM y clientes en general.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Reportar cada visita al punto de venta con fotos, datos y principales necesidades.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Responsable de coordinar el ingreso de productos con cada punto de venta, tiendas o clientes (permisos, horarios, stock, etc).</span></li><li><span style=\"color: rgb(81, 74, 72);\">Coordinación con diferentes áreas internas para asegurar los productos en el punto de venta.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Manejo de indicadores de área.</span></li></ul><p><br></p>', '<ul><li><span style=\"color: rgb(81, 74, 72);\">Formación Técnica o universitaria</span></li><li><span style=\"color: rgb(81, 74, 72);\">1 a 2 años de experiencia – prácticas, asistente o mercaderista.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Excel intermedio y SAP Básico</span></li></ul><p><br></p>', '<p>Utilidades </p><p>bonos anaules</p>', 3, '1', 2000.00, '2023-07-03 19:23:57', NULL, 'A', 'etominaga@ethconsultores.pe', '2023-07-03 19:23:57', NULL, NULL),
(41, 39, 'Ejecutivo de venta empresas - Bellavista', '<ul><li>Zona BELLAVISTA - SODIMAC</li><li><span style=\"color: rgb(81, 74, 72);\">Captar nuevos clientes, fidelizar y garantizar el correcto mantenimiento de la cartera de clientes designada a través de la ejecución de una estrategia que permita desarrollar nuevas oportunidades de negocio para alcanzar las metas individuales y grupales establecidas por la compañía. </span></li><li><span style=\"color: rgb(81, 74, 72);\">Asegurar que el resultado final de su gestión genere rentabilidad positiva para el negocio. </span></li><li><span style=\"color: rgb(81, 74, 72);\">Prospectar y negociar con nuevos clientes, de preferencia de la zona asignada.</span></li><li><span style=\"color: rgb(81, 74, 72);\">Responsable de todo el proceso de venta: prospección, captación, negociación, cotización, propuestas, cierre y seguimiento de la venta. </span></li><li><span style=\"color: rgb(81, 74, 72);\">Realizar trabajo de campo (90%) y oficina (10%)</span></li></ul><p><br></p>', '<ul><li><span style=\"color: rgb(81, 74, 72);\">Profesional técnico o universitario. </span></li><li><span style=\"color: rgb(81, 74, 72);\">1 año de experiencia en venta de tangibles. </span></li><li><span style=\"color: rgb(81, 74, 72);\">De preferencia experiencia en venta para el sector construcción, ferretería, gasfitería, muebles o similares.</span></li></ul><p><br></p>', '<p>Salario fijo S/ 1,500</p><p>Movilidad S/ 500</p><p>Variable asegurada por 3 meses S/ 1,500</p><p>Bonos </p><p>Todos los beneficios de ley</p>', 3, '2', 1500.00, '2023-07-03 19:25:55', NULL, 'A', 'etominaga@ethconsultores.pe', '2023-07-03 19:25:55', NULL, NULL),
(42, 12, 'Atención al cliente - Part time', '<p>En Beso Francés tenemos el deseo de enamorar a nuestros clientes en sus visitas. Buscamos colaboradores que desean unirse a&nbsp;nuestra cultura basada en confianza, comunicación y respeto. Te detallamos el puesto disponible:</p><p>&nbsp;</p><p>ATENCION AL CLIENTE / MULTIFUNCIONAL</p><p><br></p><p>PRINCIPALES RESPONSABILIDADES:</p><p>- Atención en caja</p><p>- Impulsar las ventas</p><p>- Elaborar los productos de la carta&nbsp;</p><p>- Realizar tareas de orden y limpieza</p><p>- Recibir, almacenar y rotar los insumos&nbsp;</p><p>- Entre otras actividades solicitadas por el puesto</p><p><br></p><p><br></p><p><br></p><p>“De acuerdo a la ley N° 29973, reglamento N° 107-2015-MIMP y normas complementarias, se reciben también postulaciones de personas con discapacidad, debidamente acreditadas y certificadas, a fin de ser evaluadas según la descripción del puesto“.</p>', '<p>- Indispensable residir cerca a la sede de preferencia&nbsp;</p><p>- Contar con disponibilidad de inmediata</p><p>- 6 meses de experiencia en atención al cliente y/o empresas de comida rápida (deseable).</p><p>- Indispensable contar con disponibilidad para realizar cierres (4-5 cierres a la semana).</p>', '<p>- Ingreso directo a planilla</p><p>- Descuentos corporativos en centros de estudios</p><p>- Descuento del 30% para consumo en productos de tiendas</p><p>- Salario Part time: Sueldo básico: S/512.50 +&nbsp;Recargo de consumo: S/105 + Bono variable de hasta S/ 200</p>', 2, '6', 650.00, '2023-07-03 19:57:23', NULL, 'A', 'ANARADO@BESOFRANCES.PE', '2023-07-03 19:57:23', NULL, NULL),
(43, 12, 'Atención al cliente - Full time', '<p>En Beso Francés tenemos el deseo de enamorar a nuestros clientes en sus visitas. Buscamos colaboradores que desean unirse a&nbsp;nuestra cultura basada en confianza, comunicación y respeto. Te detallamos el puesto disponible:</p><p>&nbsp;</p><p>ATENCION AL CLIENTE / MULTIFUNCIONAL</p><p><br></p><p>PRINCIPALES RESPONSABILIDADES:</p><p>- Atención en caja</p><p>- Impulsar las ventas</p><p>- Elaborar los productos de la carta&nbsp;</p><p>- Realizar tareas de orden y limpieza</p><p>- Recibir, almacenar y rotar los insumos&nbsp;</p><p>- Entre otras actividades solicitadas por el puesto</p><p><br></p><p><br></p><p><br></p><p>“De acuerdo a la ley N° 29973, reglamento N° 107-2015-MIMP y normas complementarias, se reciben también postulaciones de personas con discapacidad, debidamente acreditadas y certificadas, a fin de ser evaluadas según la descripción del puesto“.</p>', '<p>- Indispensable residir cerca a la sede de preferencia&nbsp;</p><p>- Contar con disponibilidad de inmediata</p><p>- 6 meses de experiencia en atención al cliente y/o empresas de comida rápida (deseable).</p><p>- Indispensable contar con disponibilidad para realizar cierres (4-5 cierres a la semana).</p>', '<p>- Ingreso directo a planilla</p><p>- Descuentos corporativos en centros de estudios</p><p>- Descuento del 30% para consumo en productos de tiendas</p><p>- Salario Part time: Sueldo básico: S/1025 +&nbsp;Recargo de consumo: S/205 + Bono variable de hasta S/ 400</p>', 3, '6', 1500.00, '2023-07-03 20:00:03', NULL, 'A', 'ANARADO@BESOFRANCES.PE', '2023-07-03 20:00:03', NULL, NULL),
(44, 46, 'Asesores Ejecutivos Movistar Empresa', '<p class=\"ql-align-justify\">¡EN FOXTEL BUSCAMOS TALENTOS COMO TÚ!</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Se parte de FOXTEL, grupo empresarial con más de 14 años de experiencia en el rubro de telecomunicaciones y actualmente socio estratégico de MOVISTAR.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Nos encontramos en la búsqueda de nuevos talentos que ocupen el puesto de <strong>ASESOR DE VENTAS</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Requisitos:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Habilidades comunicativas.</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Gestión comercial </p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Trabajo Presencial.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Funciones:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Prospección vía telefónica y seguimiento a clientes (Se brindará base de datos).</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Venta de servicios (movil y fija) de manera telefónica. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Remuneración Básica: desde S/1025 hasta S/2,000 (según experiencia laboral comprobada)</p><p class=\"ql-align-justify\">Comisiones: al 100 % sin tope de cargo fijo vendido.</p><p class=\"ql-align-justify\">Horario: lunes a viernes de 9 a.m. a 6 p.m. </p><p class=\"ql-align-justify\">Lugar de Labores: Av. José Gálvez Barrenechea 190 – La Victoria, Lima.</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p class=\"ql-align-justify\">¡TE INVITAMOS A PERTENECER A UN GRAN EQUIPO!&nbsp;</p><p><br></p>', '<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Desde 6 meses como mínimo de experiencia como asesor, promotoría y/o atención al cliente.</p><p><br></p>', '<p>Beneficios de Ley</p>', 3, '10', 1500.00, '2023-07-03 20:00:10', NULL, 'A', 'ssoria@telefonianegocios.pe', '2023-07-03 20:00:10', NULL, NULL),
(45, 46, 'Asesor Corporativo para MOVISTAR', '<p class=\"ql-align-justify\">¡EN FOXTEL BUSCAMOS TALENTOS COMO TÚ!</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Se parte de FOXTEL, grupo empresarial con más de 14 años de experiencia en el rubro de telecomunicaciones y actualmente socio estratégico de MOVISTAR.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Nos encontramos en la búsqueda de nuevos talentos que ocupen el puesto de <strong>ASESOR DE VENTAS</strong>.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Requisitos:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Habilidades comunicativas.</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Gestión comercial </p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Trabajo Presencial.</p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Funciones:</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Prospección vía telefónica y seguimiento a clientes (Se brindará base de datos).</p><p class=\"ql-align-justify\">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Venta de servicios (movil y fija) de manera telefónica. </p><p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Remuneración Básica: desde S/1025 hasta S/2,000 (según experiencia laboral comprobada)</p><p class=\"ql-align-justify\">Comisiones: al 100 % sin tope de cargo fijo vendido.</p><p class=\"ql-align-justify\">Horario: lunes a viernes de 9 a.m. a 6 p.m. </p><p class=\"ql-align-justify\">Lugar de Labores: Av. José Gálvez Barrenechea 190 – La Victoria, Lima.</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p class=\"ql-align-justify\">¡TE INVITAMOS A PERTENECER A UN GRAN EQUIPO!&nbsp;</p><p><br></p>', '<p class=\"ql-align-justify\"><br></p><p class=\"ql-align-justify\">Desde 6 meses como mínimo de experiencia como asesor, promotoría y/o atención al cliente.</p><p><br></p>', '<p>Beneficios de Ley</p>', 3, '10', 1025.00, '2023-07-03 20:01:46', NULL, 'A', 'ssoria@telefonianegocios.pe', '2023-07-03 20:01:46', NULL, NULL),
(46, 12, 'Gerente de tienda - Fast Food', '<p>En Beso Francés tenemos el deseo de enamorar a nuestros clientes en sus visitas. Buscamos colaboradores que desean unirse a&nbsp;nuestra cultura basada en la confianza, la comunicación y el respeto. Si quieres unirte a este gran equipo, te detallamos el puesto disponible:</p><p><br></p><p>ENCARGADO DE TIENDA:&nbsp;</p><p><br></p><p>PRINCIPALES RESPONSABILIDADES:</p><p>- Encargado de la elaboración de los productos de la carta y supervisar que éstos se realicen de forma correcta.</p><p>- Supervisar y realizar la atención en caja</p><p>- Supervisar, colaborar y realizar la preparación de bebidas frías y calientes</p><p>- Supervisar que las tareas de orden y limpieza se realicen de forma correcta</p><p>- Recibir, almacenar y rotar los insumos, asegurando la correcta conservación e inocuidad de los alimentos.</p><p>- Impulsar las ventas y asesorar a los colaboradores para el cumplimientos de los objetivos en tienda</p><p><br></p><p><br></p><p><br></p><p>“De acuerdo a la ley N° 29973, reglamento N° 107-2015-MIMP y normas complementarias, se reciben también postulaciones de personas con discapacidad, debidamente acreditadas y certificadas, a fin de ser evaluadas según la descripción del puesto“.</p>', '<p>- Estudios superiores en Administración de empresas y/o carreras similares&nbsp;</p><p>- Mínimo 2 años de experiencia en atención al cliente y/o empresas de comida rápida en cargos similares (indispensable)&nbsp;</p><p>- Conocimientos de excel a nivel intermedio&nbsp;</p><p>- Tener disponibilidad para cumplir con horarios rotativos (incluidos cierres)</p><p>- Horario de lunes a domingo, 1 día de descanso entre semana</p>', '<p>- Jornada Full time, disponibilidad para realizar cierres</p><p>- Ingreso directo a planilla</p><p>- Convenio con centros de estudios</p><p>- Descuentos en productos de la marca</p>', 4, '2', 2000.00, '2023-07-03 20:11:04', NULL, 'A', 'ANARADO@BESOFRANCES.PE', '2023-07-03 20:11:04', NULL, NULL),
(47, 7, 'Asistente de Recursos Humanos', '<p class=\"ql-align-center\">Importante operador logístico se encuentra en la búsqueda de un profesional para ocupar el puesto de Asistente de Recursos Humanos con disponibilidad para trabajar presencial en el distrito de San Miguel - Lima de lunes a viernes de 8:30am a 6:00pm y sábados de 9:00am a 1:00pm.</p>', '<ul><li>Profesional técnico en Recursos Humanos, Contabilidad o afines.</li><li>Experiencia mínima de 2 años en el puesto.</li><li>Experiencia indispensable en elaboración de planillas, cálculo de beneficios sociales, pagos de afp, trámite de subsidios y control de asistencia.</li><li>Conocimiento en legislación laboral y en SST.</li><li>Manejo de Windows, MS Office y SINTAD.</li><li>Perfil: Organización, confidencialidad, comunicación clara y asertiva, dinamismo e iniciativa.</li><li>Habilidad de redacción, concentración, precisión de datos.</li></ul>', '<ul><li>Ingreso a planilla con todos los beneficios según ley.</li><li>Buen clima laboral y aprendizaje continuo.</li><li>Capacitación constante.</li></ul>', 4, '1', 1800.00, '2023-07-03 21:10:31', NULL, 'A', 'rhumanos.seleccion01@gmail.com', '2023-07-03 21:10:31', NULL, NULL),
(48, 80, 'Trainee de Infraestructura Cloud', '<p><strong style=\"color: rgb(68, 68, 68);\">Misión del puesto:</strong><span style=\"color: rgb(68, 68, 68);\"> Atender requerimientos e incidencias y administrar sistemas operativos y entornos Cloud para asegurar el correcto funcionamiento del área. </span></p><p><strong style=\"color: rgb(68, 68, 68);\">Funciones</strong></p><ol><li><span style=\"color: rgb(68, 68, 68);\">Atender requerimientos e incidentes de Infraestructura Cloud, de forma progresiva de acuerdo al aprendizaje, para garantizar el soporte adecuado.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Administrar los Sistemas Operativos, para garantizar los recursos de hardware y de redes.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Administrar los entornos Cloud de los principales proveedores Cloud públicos, garantizando la continuidad del servicio.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Elaborar reportes ejecutivos, con el fin de brindar información actualizada sobre el servicio.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Participar en proyectos internos y externos de Infraestructura Cloud.<span class=\"ql-cursor\">﻿﻿</span></span></li></ol>', '<ul><li>Estudiante de los últimos ciclos o recién egresado de las carreras de Ing. de sistemas, computación e informática y afines.</li><li>Conocimiento básico en Sistemas Operativos: Windows Server y Linux</li><li>Conocimiento básico en base de datos a nivel usuario (SQL)</li><li>Conocimiento básico en redes</li></ul>', '<ul><li>Planilla completa desde el primer día</li><li>EPS</li><li>Beneficios corporativos</li><li>Línea de carrera</li><li>Buen clima laboral</li><li>Ser parte de una empresa transnacional líder en su rubro</li></ul>', 2, '1', NULL, '2023-07-03 22:55:01', NULL, 'A', 'ingrid.castillo@seidor.com', '2023-07-03 22:55:01', 'ingrid.castillo@seidor.com', '2023-07-04 17:34:31'),
(49, 80, 'Trainee Centro de Operaciones', '<p><strong>Misión del puesto:</strong> Ejecutar las tareas asignadas dentro del equipo de operaciones así como los objetivos planteados a fin de ganar conocimiento y experiencia en los servicios ofrecidos por la organización y continuar ascendiendo por la línea de carrera.</p><p><strong>Funciones:</strong></p><ol><li>Comunicar los tickets a los equipos internos de Seidor Technologies, luego de realizar las validaciones, para su atención.</li><li>Coordinar y asignar a los especialistas los tickets con el objetivo de resolver el caso.</li><li>Supervisar el correcto funcionamiento de los servidores mediante las herramientas proporcionadas con la finalidad asegurar la disponibilidad del servicio.</li><li>Atender requerimientos de aplicación SAP, Infraestructura Cloud y Digital Workplace de forma progresiva de acuerdo al aprendizaje.</li><li>Elaborar informes y reportes ejecutivos para mantener la información al día.</li><li>Monitorear y elaborar informes de control.</li></ol>', '<ul><li>Estudiantes universitarios o técnicos de los últimos ciclos.</li><li>Deseable conocimientos en: Base de datos, Sistemas operativos (windows o linux), Redes (AWS), soporte TI (ITIL).</li></ul>', '<ul><li>Planilla completa desde el primer día</li><li>EPS</li><li>Beneficios corporativos</li><li>Línea de carrera</li><li>Buen clima laboral</li><li>Ser parte de una empresa transnacional líder en su rubro.</li></ul>', 2, '2', NULL, '2023-07-03 23:05:47', NULL, 'A', 'ingrid.castillo@seidor.com', '2023-07-03 23:05:47', NULL, NULL),
(50, 80, 'Programador .NET', '<p>Funciones:</p><ul><li>Analizar nuevos requerimientos de productos en conjunto con el cliente.</li><li>Probar y validar el funcionamiento de los desarrollos realizados, con el objetivo de poder presentar a los cliente las soluciones y productos desarrollados, cumpliendo con los estándares de calidad definidos por el área.</li><li>Capacitar a clientes en el uso de las soluciones y productos desarrollados.</li><li>Acompañar a los clientes en las salidas en vivos de los proyectos</li><li>Resolver incidencias reportadas por el área de soporte con relación a los aspectos técnicos de los desarrollos</li></ul>', '<ul><li>Experiencia en Desarrollo .Net</li><li>Conocimiento en Base de Datos</li><li>Conocimientos/ experiencia en desarrollo web y mobile</li></ul>', '<ul><li>Planilla completa desde el primer día</li><li>EPS</li><li>Beneficios corporativos</li><li>Línea de carrera</li><li>Buen clima laboral </li><li>Ser parte de una empresa líder en su rubro</li></ul>', 3, '3', NULL, '2023-07-03 23:17:21', NULL, 'A', 'ingrid.castillo@seidor.com', '2023-07-03 23:17:21', NULL, NULL),
(51, 80, 'Consultor Trainee - SAP', '<p>Misión del puesto: Ejecutar las tareas indicadas por el gerente de proyectos/consultores senior a fin de entrenarse y ganar experiencia como consultor funcional. </p><p>Funciones:</p><ol><li><span style=\"color: rgb(68, 68, 68);\">Ejecución de pruebas de consultoría de los productos de localización. </span></li><li><span style=\"color: rgb(68, 68, 68);\">Elaborar documentación: Documento de pruebas, BPD, EF, Guías de usuario de los productos en los proyectos.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Apoyar a los consultores senior del área en configuraciones.</span></li><li><span style=\"color: rgb(68, 68, 68);\">Aportar ideas para mejora de productos actuales y para generación de nuevas soluciones</span></li></ol>', '<ul><li>Nivel de inglés Intermedio (indispensable)</li><li>Conceptos básicos de SAP</li><li>Conceptos básicos de contabilidad</li></ul>', '<ul><li>Planilla completa desde el primer día</li><li>EPS</li><li>Beneficios corporativos</li><li>Línea de carrera</li><li>Buen clima laboral </li><li>Ser parte de una empresa líder en su rubro</li></ul>', 1, '1', NULL, '2023-07-03 23:27:43', NULL, 'A', 'ingrid.castillo@seidor.com', '2023-07-03 23:27:43', 'ingrid.castillo@seidor.com', '2023-07-04 17:34:02'),
(52, 28, 'Asistente de Facturación', '<p>Corporación E. Wong se encuentra en la búsqueda de personal para laborar en el Centro Comercial Plaza Norte en el área de facturación, responsable de verificar la emisión y revisión de comprobantes de pago para asegurar el cumplimento de la facturación.</p><p><br></p><p><strong><u>FUNCIONES:</u></strong></p><ul><li>Ejecutar los procedimientos correspondientes para la emisión de comprobantes de pago.</li><li>Analizar la información relacionada a la facturación, a nivel de conceptos e importes.</li><li>Atender y dar solución a las consultas de los clientes, en relación a los cálculos y conceptos facturados.</li><li>Coordinar y gestionar con las áreas involucradas, los conceptos e importes a facturar.</li><li>Registrar información de los clientes en el sistema.</li><li>Generar reportes de los conceptos facturados.</li><li>Verificación de comprobantes en el portal de Sunat.</li></ul>', '<ul><li>Experiencia mínima de 1 año en áreas de facturación, administración o afines.</li><li>Titulado de la carrera de contabilidad.</li><li>Disponibilidad para laborar a tiempo completo en el distrito de Independencia (CC Plaza Norte).</li><li>Microsoft Office </li><li>Manejo de SAP</li></ul>', '<ul><li>Línea de carrera</li><li>Descuentos corporativos</li><li>Capacitación constante</li></ul>', 3, '1', 2000.00, '2023-07-04 13:39:48', NULL, 'A', 'abarreda@wong.net.pe', '2023-07-04 13:39:48', NULL, NULL),
(53, 18, 'DESARROLLADOR JUNIOR FRONTEND VUE.JS', '<h4 class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Condiciones del puesto:</strong></h4><p class=\"ql-align-justify\"><strong style=\"background-color: transparent;\">Horario:</strong><span style=\"background-color: transparent;\"> Full time. 48 horas semanales. Lunes - sábado</span></p><p class=\"ql-align-justify\"><strong style=\"background-color: transparent;\">Modalidad: </strong><span style=\"background-color: transparent;\">Teletrabajo</span></p><p class=\"ql-align-justify\"><br></p><h4 class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Funciones específicas del área:</strong></h4><ul><li><span style=\"background-color: transparent;\">Desarrollar funcionalidades y mejoras de los productos de FractalUp de manera segura, bien comprobada y optimizada.</span></li><li><span style=\"background-color: transparent;\">Elaborar código que cumpla con nuestros estándares internos de estilo, mantenimiento y mejores prácticas para un entorno web escalable.</span></li><li><span style=\"background-color: transparent;\">Realizar pruebas de los programas desarrollados a través de pruebas unitarias y funcionales.</span></li><li><span style=\"background-color: transparent;\">Realizar integraciones de API de terceros.</span></li></ul><p><br></p><h4 class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Etapas del Proceso de Selección:</strong></h4><ol><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Speed Meeting. 3 min</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Entrevista profunda. 20 min</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Reto Técnico. 9 horas.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Capacitación: 6 días full</span></li></ol><p><br></p>', '<h4><span style=\"color: rgb(230, 0, 0);\">Conocimientos en:</span></h4><ul><li><span style=\"background-color: transparent;\">Experiencia básica en Vue.js</span></li><li><span style=\"background-color: transparent;\">Experiencia trabajando en Ubuntu.</span></li><li><span style=\"background-color: transparent;\">Comprensión de HTML, CSS y Javascript.</span></li><li><span style=\"background-color: transparent;\">Conocimiento de programación orientado a objetos.</span></li></ul><p><br></p><h4 class=\"ql-align-justify\"><span style=\"color: rgb(230, 0, 0); background-color: transparent;\">Requisitos obligatorios:</span></h4><ul><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Computadora o Laptop Core i5.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Internet mínimo 5Mbps de subida.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Firma de CLS y legalización en Notaría.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Envío de documentos a oficinas en Trujillo.</span></li></ul><p><br></p>', '<ul><li><span style=\"background-color: transparent;\">Capacitación intensiva&nbsp; en Vue.js 6 días no remunerado.&nbsp;</span></li><li><span style=\"background-color: transparent;\">Flexibilidad horaria a los 8 meses de tu ingreso.&nbsp;</span></li><li><span style=\"background-color: transparent;\">100% Trabajo remoto desde la comodidad de tu hogar.</span></li><li><span style=\"background-color: transparent;\">Aprenderás en 01 año, lo que te tomaría 5 años en el mundo corporativo.</span></li><li><span style=\"background-color: transparent;\">Obtener experiencia real y valiosa desde el primer día.</span></li></ul><p><br></p>', 3, '3', NULL, '2023-07-04 15:10:55', NULL, 'A', 'talento.fractalup@gmail.com', '2023-07-04 15:10:55', 'talento.fractalup@gmail.com', '2023-07-04 15:12:01'),
(54, 18, 'ASISTENTE DE OPERACIONES DIGITALES & QA', '<h4 class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Condiciones del puesto:</strong></h4><p class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Horario:</strong><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"> Full time. 48 horas semanales. Lunes - sábado</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Modalidad: </strong><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Teletrabajo</span></p><p><br></p><h4 class=\"ql-align-justify\"><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Requisitos obligatorios:</strong></h4><ul><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Computadora o Laptop Core i5.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Internet mínimo 5Mbps de subida.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Firma de contrato y legalización en Notaría.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Envío de documentos a oficinas en Trujillo.</span></li></ul><p class=\"ql-align-justify\"><br></p><h4><strong style=\"background-color: transparent; color: rgb(230, 0, 0);\">Funciones específicas del área:</strong></h4><ul><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Simulaciones y testeo del rendimiento de nuestra plataforma y evaluar los resultados.</span></li><li class=\"ql-align-justify\">Comunicar los resultados a los desarrolladores de software.</li><li class=\"ql-align-justify\">Participación en demos con clientes internacionales.</li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Redacción de informes y otros documentos a solicitud.</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Soporte administrativo y personal para altos directivos y equipo de gestión de FractalUp.</span></li></ul><p><br></p>', '<p class=\"ql-align-justify\"><strong style=\"background-color: transparent;\">Soft Skills:</strong></p><ul><li><span style=\"background-color: transparent;\">Habilidades comunicativas y de improvisación, demostrando confianza y seguridad.</span></li><li><span style=\"background-color: transparent;\">Habilidades de redacción para redactar correos, informenes, y otros.</span></li><li><span style=\"background-color: transparent;\">Compromiso y flexibilidad para garantizar la calidad del software y la satisfacción del cliente.</span></li><li><span style=\"background-color: transparent;\">Capacidad de aprendizaje rápido.</span></li><li><span style=\"background-color: transparent;\">Orientación al detalle.</span></li><li><span style=\"background-color: transparent;\">Multitasking.&nbsp;</span></li></ul><p><br></p><p><strong style=\"background-color: transparent;\">Hard Skills:</strong></p><p><br></p><ul><li><span style=\"background-color: transparent;\">Experiencia en pruebas de software y control de calidad (QA).</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Inglés intermedio</span></li><li class=\"ql-align-justify\"><span style=\"background-color: transparent;\">Manejo de MsOffice (power point, Word, Excel) nivel intermedio.</span></li></ul><p><br></p>', '<ul><li><span style=\"background-color: transparent;\">100% Trabajo remoto desde la comodidad de tu hogar.</span></li><li><span style=\"background-color: transparent;\">&nbsp;Mucha autonomía y ownership en todos tus proyectos para que te conviertas en un experto en lo que haces.</span></li><li><span style=\"background-color: transparent;\">&nbsp;Obtener experiencia real y valiosa desde el primer día.</span></li><li><span style=\"background-color: transparent;\">&nbsp;Aprenderás en 01 año, lo que te tomaría 5 años en el mundo corporativo.</span></li><li><span style=\"background-color: transparent;\">&nbsp;Desempeñarás varios roles a la vez y estarás expuesto a diferentes áreas de la empresa.&nbsp;</span></li><li><span style=\"background-color: transparent;\">&nbsp;Ambiente de trabajo dinámico: colaborar con profesionales de diversos campos.</span></li><li><span style=\"background-color: transparent;\">Participación de proyectos emocionante e innovadores internacionales.</span></li></ul><p><br></p>', 3, '3', NULL, '2023-07-04 15:17:30', NULL, 'A', 'talento.fractalup@gmail.com', '2023-07-04 15:17:30', NULL, NULL),
(55, 49, 'Griferos (as)', '<p><em style=\"color: rgb(66, 66, 66);\">Somos una empresa dedicada al sector de hidrocarburos y nos encontramos en la búsqueda del mejor talento y disposición para la posición de GRIFEROS(AS).</em></p>', '<p>- Jovenes 21 a 27 años</p><p>- Experiencia mínima en ventas y/o atención al cliente en grifo de 3 meses (deseable)</p><p>- Experiencia en caja y manejo de POS (recomendable)</p><p>- Vivir en zonas aledañas al grifo (Villa Maria del Triunfo , Lurin o Villa el Salvador, abstenerse a la postulación en caso no cumpla con este requisito)</p><p>- Turnos rotativo mañana, tarde o noche de lunes a domingo con un día de descanso a la semana rotativo</p><p>- Disponibilidad inmediata</p><p>- Compromiso, proactividad y alto grado de responsabilidad</p>', '<ul><li>Facilidad de horarios para estudiantes de cualquier carrera y/o ciclo</li><li>Capacitación pagada </li></ul>', 1, '4', 1025.00, '2023-07-04 15:33:48', NULL, 'A', 'hytek.autogas@hotmail.com', '2023-07-04 15:33:48', NULL, NULL),
(56, 38, 'Senior/Mid Java Developer', '<p>En Encora estamos en búsqueda de un gran talento como tu para que se una a nuestro equipo como el próximo&nbsp;<strong><em>Senior Java Developer</em></strong></p><p><br></p><p>¿Te animas a unirte a nuestro gran equipo de ingenieros? Te invitamos a leer más de nosotros y conocer nuestra posición en búsqueda</p><p><br></p><p><strong><u>Sobre el rol</u></strong>:</p><ul><li>Diseñar los servicios y microservicios de acuerdo con la definición de Arquitectura.</li><li>Implementar los servicios y microservicios aplicando todo el ciclo de vida de la metodología DevOps (Plan, Análisis, Diseño, Construcción, Testing y Producción).</li><li>Ejecutar las pruebas unitarias e integrales en el ambiente de Desarrollo.</li><li>Apoyar y dar soporte a las pruebas del ambiente de calidad y corregir las observaciones que se originen por la implementación de los componentes.</li><li>Participar activamente en reuniones de trabajo de los proyectos y comités de promoción entre diferentes ambientes.</li><li>Apoyar y dar soporte al pase a producción y contingencia.</li><li>Cumplir con los formatos y procedimientos establecidos de Mibanco.</li></ul><p><br></p><p><br></p>', '<p><u>Requisitos para la vacante</u>:</p><p><br></p><ul><li>Java Backend</li><li>+ 3 años desarrollando en Java 8 en adelante</li><li>Spring 4</li><li>Spring boot</li><li>Spring Web Service</li><li>Maven</li><li>Jboss</li><li>Oracle (deseable)</li><li>SQL intermedio o avanzado</li></ul><p><br></p>', '<p><u>Por qué te encantará trabajar con nosotros:</u></p><ul><li>Trabajo Remoto: Trabajaras desde casa y tendrás la opción de ir a oficina cuando gustes.</li><li>Seguro médico cubierto al 100%</li><li>Bonos por referidos</li><li>Día libre de cumpleaños</li><li>Horarios y modelos de trabajo flexibles para un mayor equilibrio entre la vida laboral y personal</li><li>Formación técnica continua y capacitaciones constantes</li><li>Trabajar en una Great Place To Work caracterizada por un clima horizontal y dinámico</li><li>Programa de reconocimientos corporativo</li><li>Línea de carrera que te permitirá crecer con nosotros</li><li>Entre otros</li></ul><p><br></p>', 5, '2', NULL, '2023-07-04 16:55:22', NULL, 'A', 'estefania.ludenas@encora.com', '2023-07-04 16:55:22', NULL, NULL),
(57, 38, 'Senior Software Engineer', '<p>En Encora estamos en búsqueda de un gran talento como tu para que se una a nuestro equipo como el próximo&nbsp;<strong><em>Senior Software Engineer </em></strong></p><p>¿Te animas a unirte a nuestro gran equipo de ingenieros? Te invitamos a leer más de nosotros y conocer nuestra posición en búsqueda</p><p><strong><u>Sobre el rol</u></strong>:</p><p>Como un&nbsp;<strong><em>Senior Software Engineer,</em></strong> formarás parte de un equipo tecnológico y ágil altamente calificado por respaldar y desarrollar soluciones de vanguardia para cumplir con los requisitos de nuestro negocio. Nos ayudará a acelerar los resultados empresariales de nuestros clientes mediante la innovación de productos digitales de vanguardia.</p><p>Algunos de tus deberes esenciales y responsabilidades laborales del día a día serán:</p><ul><li>Crear programas informáticos que satisfagan las&nbsp;necesidades de la sociedad y empresas.</li><li>Guiar y coordinar el<strong>&nbsp;</strong>desarrollo de una programación difícil.</li><li>Intervenir en el ciclo de vida de un producto.</li><li>Estimar los&nbsp;costos y el plazo de ejecución de un proyecto.</li></ul><p><br></p>', '<p><strong><u>Requisitos para la vacante</u></strong>:</p><p>&nbsp;</p><ul><li>Conocimientos avanzados de cobol CICS y Batch. (Más de 5 años)</li><li>&nbsp;Conocimientos avanzados en JCLs. (Más de 5 años)</li><li>&nbsp;Conocimientos básicos de la herramienta Control M v9.0.</li><li>&nbsp;Conocimientos básicos en el uso de la herramienta debug tools de IBM para depurar código.</li><li>&nbsp;Conocimientos básicos de la herramienta OPE para la gestión de componentes Mainframe.</li><li>&nbsp;Uso del TSO, IDZ y ROSCOE para desarrollo de aplicaciones Cobol. (De preferencia IDZ)</li><li>&nbsp;Conocimientos básicos en DB2 como desarrollador (select, insert y delete).</li><li>&nbsp;Elaboración de la documentación técnica y pruebas unitarias de cada requerimiento.</li><li>&nbsp;Conocimientos básicos de los procesos de Medios de Pago.</li></ul><p>&nbsp;</p><p>Deseable:</p><ul><li>Análisis de la trama ISO 8583 de VISA, Mastercard, AMEX y FIS</li><li>Conocimientos intermedios de autorizaciones.&nbsp;</li><li>Conocimientos básicos del switch transacciones Connex.&nbsp;</li><li>Conocimientos básicos en el uso y navegación de Connex.&nbsp;</li><li>Conocimientos básicos de los procesos batch de Connex.&nbsp;</li></ul><p><br></p>', '<p><strong><u>Por qué te encantará trabajar con nosotros:</u></strong></p><ul><li>Trabajo Remoto: Trabajaras desde casa y tendrás la opción de ir a oficina cuando gustes.</li><li>Seguro médico cubierto al 100%</li><li>Bonos por referidos</li><li>Día libre de cumpleaños</li><li>Horarios y modelos de trabajo flexibles para un mayor equilibrio entre la vida laboral y personal</li><li>Formación técnica continua y capacitaciones constantes</li><li>Trabajar en una Great Place To Work caracterizada por un clima horizontal y dinámico</li><li>Programa de reconocimientos corporativo</li><li>Línea de carrera que te permitirá crecer con nosotros</li><li>Entre otros</li></ul><p><br></p>', 5, '2', NULL, '2023-07-04 16:56:30', NULL, 'A', 'estefania.ludenas@encora.com', '2023-07-04 16:56:30', NULL, NULL),
(58, 38, 'Mid Java AWS Developer', '<p>En Encora estamos en búsqueda de un gran talento como tu para que se una a nuestro equipo como el próximo <strong><em>Mid Java AWS Developer (10262)</em></strong></p><p>¿Te animas a unirte a nuestro gran equipo de ingenieros? Te invitamos a leer más de nosotros y conocer nuestra posición en búsqueda</p><p><strong><u>Sobre el rol</u></strong>:</p><p>Como un <strong><em>Mid Java AWS Developer, </em></strong>formarás parte de un equipo tecnológico y ágil altamente calificado por respaldar y desarrollar soluciones de vanguardia para cumplir con los requisitos de nuestro negocio. Nos ayudará a acelerar los resultados empresariales de nuestros clientes mediante la innovación de productos digitales de vanguardia.</p><p>Algunos de tus deberes esenciales y responsabilidades laborales del día a día serán:</p><ul><li>Optimizar las aplicaciones para que rindan mejor y de forma más rápida.</li><li>Garantizar la seguridad de todo el entorno.</li><li>Solucionar posibles errores que se vayan detectando.</li><li>Gestionar e integrar las bases de datos necesarias.</li></ul><p><br></p>', '<p><strong><u>Requisitos para la vacante</u></strong>:</p><ul><li>+ 3 años de experiencia en desarrollo backend con Java.</li><li>+ 2 años de experiencia en manejo de Unit Testig.</li><li>+ 2 años de experiencia con microservicios.</li><li>+ 2 años de experiencia con Java 8 en adelante</li><li>Experiencia con JUnit o Mockito</li><li>Experiencia con Base de Datos como SQL, MySQL, Oracle, Mongo, otros.</li><li>+ 2 años de experiencia con Spring y Springboot</li><li>Experiencia con Kakfa o Neiven.</li><li>Conocimiento de principios SOLID (modo práctico y/o teórico)</li><li>Conocimiento de programacion orientada a objetos</li><li>Dominio de principios SOLID y Patrones de diseño (enfocado en buenas prácticas de código y diseño)</li><li>Conocimiento de programacion orientada a objetos - Experiencia con APIs: REST y/o GraphQL.</li></ul><p><br></p>', '<p><strong><u>Por qué te encantará trabajar con nosotros:</u></strong></p><ul><li>Trabajo Remoto: Trabajaras desde casa y tendrás la opción de ir a oficina cuando gustes.</li><li>Seguro médico cubierto al 100%</li><li>Bonos por referidos</li><li>Día libre de cumpleaños</li><li>Horarios y modelos de trabajo flexibles para un mayor equilibrio entre la vida laboral y personal</li><li>Formación técnica continua y capacitaciones constantes</li><li>Trabajar en una Great Place To Work caracterizada por un clima horizontal y dinámico</li><li>Programa de reconocimientos corporativo</li><li>Línea de carrera que te permitirá crecer con nosotros</li><li>Entre otros</li></ul><p><br></p>', 4, '1', NULL, '2023-07-04 16:58:37', NULL, 'A', 'estefania.ludenas@encora.com', '2023-07-04 16:58:37', NULL, NULL),
(59, 115, 'PRACTICANTE PROFESIONAL O RECIÉN EGRESADO DE MARKETING', '<p>- Ser recién egresado en carreras de Diseño Gráfico, Marketing o carreras afines.</p><p>- Conocimiento intermedio – avanzado de paquete de Adobe (Illustrator, Photoshop, InDesing, Premiere, Corel Draw)</p><p>- Con conocimiento en manejo de edición de imágenes y videos.</p><p>- Elaborar diseños creativos, desarrollar y/o adaptar, cuando corresponda, materiales promocionales, afiches, hojas de ventas, catálogos, etc.</p><p>- Seguir y gestionar las redes sociales, a fin de contribuir, administrar y mantener las páginas actualizadas.&nbsp;</p><p>- Facilidad de manejo de entrevista.</p><p>- Contar con excelente ortografía y redacción.</p>', '<p>- Ser recién egresado en carreras de Diseño Gráfico, Marketing o carreras afines.</p><p>- Conocimiento intermedio – avanzado de paquete de Adobe (Illustrator, Photoshop, InDesing, Premiere, Corel Draw)</p><p>- Con conocimiento en manejo de edición de imágenes y videos.</p><p>- Elaborar diseños creativos, desarrollar y/o adaptar, cuando corresponda, materiales promocionales, afiches, hojas de ventas, catálogos, etc.</p><p>- Seguir y gestionar las redes sociales, a fin de contribuir, administrar y mantener las páginas actualizadas.&nbsp;</p><p>- Facilidad de manejo de entrevista.</p><p>- Contar con excelente ortografía y redacción.</p>', '<p>- Oportunidad de línea de carrera y desarrollo profesional.</p><p>- Buen ambiente laboral.</p><p>- Sueldo de acuerdo al mercado y pagos puntuales.</p><p><br></p>', 3, '1', NULL, '2023-07-04 17:15:43', NULL, 'A', 'rnunez@ginsac.pe', '2023-07-04 17:15:43', 'rnunez@ginsac.pe', '2023-07-04 17:16:51'),
(60, 57, 'SURQUILLO / ATENCIÓN AL CLIENTE NIUBIZ PRESENCIAL', '<p><strong style=\"color: rgb(31, 56, 100);\">Descripción</strong><span style=\"color: rgb(31, 56, 100);\">: Atender las llamadas entrantes de empresas Mypes que hacen uso del servicio Niubiz, dando soporte en sus consultas o reclamos,cumpliendo con los protocolos de atención definidos y asegurando una atención de calidad.</span></p><p>  </p><p><span style=\"color: rgb(31, 56, 100);\">- Jornada Laboral: 48 hrs. Semanales (8Hrs + 1 de Refrigerio).</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Descanso: Fijo Domingos.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Turno: Lunes a Sábado. Disponibilidad 10 am a 20 pm (10 am a 7 pm / 11 am a 8 pm).</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Modalidad de trabajo: PRESENCIAL.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Capacitación pagada: s/25 por día asistido.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Rango Salarial: Sueldo Fijo + 25% de variable (según indicadores).</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Lugar de trabajo: </span></p><p><span style=\"color: rgb(31, 56, 100);\">Av. Republica de Panamá 4575 - Surquillo (Ref. al costado del Edificio Nissan)</span></p><p><br></p><p><strong style=\"color: rgb(31, 56, 100);\">Postula Aquí: </strong><strong>https://forms.gle/9ZYozY53ZA7Xeu1R6</strong></p>', '<p><strong style=\"color: rgb(31, 56, 100);\">Requisitos: </strong></p><p><br></p><p><span style=\"color: rgb(31, 56, 100);\">- Secundaria completa.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Carreras de administración, negocios, comunicaciones o afines. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Deseable experiencia en call center.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Manejo de PC a nivel usuario.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Manejo de Excel y bases de datos a nivel básico.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Fluidez de palabra, compromiso, ganas de aprender, empatía y solución de problemas.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- De acuerdo a la campaña, es probable que la capacitación sea remota. Contar con dispositivo para conectarse.&nbsp;</span></p>', '<p><strong style=\"color: rgb(31, 56, 100);\">Beneficios:</strong></p><p><span style=\"color: rgb(31, 56, 100);\">- Beneficios de ley: CTS, gratificaciones, seguro de salud, vacaciones, asignación familiar, entre otros.</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Beneficios Konecta:</span></p><p><span style=\"color: rgb(31, 56, 100);\">- Plan de Línea de carrera - A partir del 3er mes de gestión, puedes postular a nuestras convocatorias internas. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Convenios y descuentos corporativos. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Conciencia de pagos: pagos puntuales. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Licencias. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Préstamos personales. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Asesoría jurídica. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Acompañamiento psico laboral. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Plan de desarrollo personal. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Programa de atención médica privada gratuito. </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Programa de Inclusión, Responsabilidad social, Víctimas de violencia, y Población vulnerable (INKLUYE). </span></p><p><span style=\"color: rgb(31, 56, 100);\">- Excelente clima laboral.</span></p>', 2, '30', 1150.00, '2023-07-04 17:24:57', NULL, 'A', 'david.montero@grupokonecta.com', '2023-07-04 17:24:57', 'david.montero@grupokonecta.com', '2023-07-04 17:26:37');
