(142, 136, 'Representante Financiero Part Time', '<p><strong>Funciones:&nbsp;</strong></p><p><br></p><ul><li>Procesar transacciones financieras en los sistemas</li><li>Resolver las consultas y reclamos de los clientes</li><li>Promover y vender los productos del banco</li><li>Participar en las promociones del banco, informando al cliente</li><li>Realizar tareas afines indicadas por su Gerente Asistente</li></ul><p><br></p>', '<ul><li>Estudios técnicos y/o universitarios en curso o truncos</li><li>Deseable experiencia de 6 meses en ventas y atención al cliente</li><li>Office a nivel usuario</li></ul><p><br></p>', NULL, 1, '1', NULL, '2023-07-06 22:49:57', NULL, 'A', 'Fbahamondec@intercorp.con.pe', '2023-07-06 22:49:57', NULL, NULL),
(143, 136, 'Representante Financiero Digital Full Time', '<p>Funciones:&nbsp;</p><p><br></p><ul><li>Aborda a los clientes en el patio brindando un trato cordial, haciendo que se sientan cómodos durante la espera</li><li>Atender y/o derivar adecuadamente las necesidades de los clientes que surgen en el patio de la tienda</li><li>Educar a los clientes en el uso de ATM para derivación de depósitos, retiros, pago de TC y las funcionalidades que surjan</li><li>Enseñar a los clientes a registrarse por si solos en el sistema de colas de la tienda</li><li>Educar a los clientes en las nuevas capacidades digitales del banco, que incluyen nuevos desarrollos en canales APP y BPI y nuevos aplicativos como Billy o Tunki</li><li>Incrementar la venta digital a través de la página web del banco</li></ul><p><br></p>', '<p>Requisitos:&nbsp;</p><ul><li>Estudios técnicos y/o universitarios en curso o truncos</li><li>Deseable experiencia de 6 meses en ventas y atención al cliente</li><li>Office a nivel usuario</li></ul><p><br></p>', NULL, 1, '5', NULL, '2023-07-06 22:51:09', NULL, 'A', 'Fbahamondec@intercorp.con.pe', '2023-07-06 22:51:09', NULL, NULL),
